import axios from 'axios';
import AsyncStorage from '@react-native-async-storage/async-storage';

// Base API configuration
const API_BASE_URL = 'http://localhost:3000'; // Update this to your backend URL

// Create axios instance with default config
const apiClient = axios.create({
  baseURL: API_BASE_URL,
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor to add auth token
apiClient.interceptors.request.use(
  async (config) => {
    try {
      const token = await AsyncStorage.getItem('authToken');
      if (token) {
        config.headers.Authorization = `Bearer ${token}`;
      }
    } catch (error) {
      console.error('Error getting auth token:', error);
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Response interceptor for error handling
apiClient.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      // Handle unauthorized access
      console.log('Unauthorized access, redirecting to login');
    }
    return Promise.reject(error);
  }
);

// Auth API endpoints
export const authAPI = {
  login: (credentials) => apiClient.post('/auth/login', credentials),
  register: (userData) => apiClient.post('/auth/register', userData),
  logout: () => apiClient.post('/auth/logout'),
  verifyToken: () => apiClient.get('/auth/verify'),
};

// User API endpoints
export const userAPI = {
  getProfile: () => apiClient.get('/users/profile'),
  updateProfile: (data) => apiClient.put('/users/profile', data),
  getTransactions: () => apiClient.get('/users/transactions'),
  getBalance: () => apiClient.get('/users/balance'),
};

// Payment API endpoints
export const paymentAPI = {
  getCards: () => apiClient.get('/payments/cards'),
  addCard: (cardData) => apiClient.post('/payments/cards', cardData),
  removeCard: (cardId) => apiClient.delete(`/payments/cards/${cardId}`),
  makePayment: (paymentData) => apiClient.post('/payments/process', paymentData),
  getPaymentHistory: () => apiClient.get('/payments/history'),
};

// QR API endpoints
export const qrAPI = {
  generateQR: (data) => apiClient.post('/qr/generate', data),
  scanQR: (qrData) => apiClient.post('/qr/scan', qrData),
  getQRHistory: () => apiClient.get('/qr/history'),
};

export default apiClient;
